package com.nigson.acceptance.pricing;

import com.nigson.commerce.pricing.*;
import com.nigson.commerce.cart.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.ActorAssertion;
import com.nigson.shared.events.EventCodec;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class AutomaticPartnerPricingTest {
 PricingFixture f;PricingAuthority authority;CartService carts;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new PricingFixture(jdbc,manager);f.retail();var clock=Clock.systemUTC();authority=new PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY");carts=new CartService(new JdbcCartRepository(jdbc,clock,new JdbcPricing(jdbc,3),3),authority,jdbc,new PlatformStore(jdbc,manager,clock,f.metrics),new AuditWriter(jdbc,clock,f.metrics),f.metrics,manager);}
 @AfterEach void cleanup(){if(f!=null){f.jdbc.update("DELETE FROM commerce.standard_sku_price WHERE sku_id=?",f.sku);f.close();}}
 UUID partner(String type){UUID org=f.organization();f.jdbc.update("UPDATE commerce.account_entitlement SET partner_type=? WHERE organization_id=?",type,org);return org;}
 UUID price(String type,String amount,String minimum){var base=f.input(amount);var draft=f.books.create(f.sales,new PricingValues.Input(f.code+"_"+UUID.randomUUID().toString().substring(0,8),"NGN",type,base.effectiveFrom(),base.effectiveUntil(),List.of(new PricingValues.Entry(f.sku,minimum,amount))),UUID.randomUUID().toString(),UUID.randomUUID());var book=f.books.activate(f.finance,draft.id(),0,"Synthetic standard price activation",UUID.randomUUID().toString(),UUID.randomUUID());f.jdbc.update("INSERT INTO commerce.standard_sku_price(id,created_by,updated_by,market_id,sku_id,segment,price_book_id) VALUES (?,'test','test',?,?,?,?) ON CONFLICT(market_id,sku_id,segment) DO UPDATE SET price_book_id=EXCLUDED.price_book_id,version=commerce.standard_sku_price.version+1",UUID.randomUUID(),f.market,f.sku,type,book.id());return book.id();}
 @Test void browserSessionPriceAndCartUseTheSameBusinessContext()throws Exception {
  partner("WHOLESALE");price("WHOLESALE","7.00","10");
  var sessions=org.mockito.Mockito.mock(com.nigson.commerce.security.JdbcSessionTrust.class);String id=UUID.randomUUID().toString();var now=Instant.now();var record=new com.nigson.commerce.security.SessionRecord(1,f.customer.party(),f.customer.identityIssuer(),f.customer.identitySubject(),now,null,"synthetic-access","synthetic-refresh",now.plusSeconds(300),"a".repeat(43),com.nigson.commerce.security.SessionRecord.TokenState.READY);
  org.mockito.Mockito.when(sessions.read(id,true)).thenReturn(record);
  var boundary=new com.nigson.commerce.security.TrustFilter(null,sessions,new com.nigson.commerce.security.SessionCookies("local",true),new com.nigson.commerce.security.CommerceAuthority(f.jdbc,Clock.systemUTC(),3),new ProblemWriter("test",""),new com.nigson.commerce.security.BrowserBoundary("test",Set.of("https://bff.synthetic.test")));
  var controller=new PricingController(f.books,f.prices,f.quotes,f.assignments);String route="/api/v1/catalogue/skus/"+f.sku+"/price";
  try{
   var request=new org.springframework.mock.web.MockHttpServletRequest("GET",route);request.setCookies(new jakarta.servlet.http.Cookie("nigson-local-session",id));request.addParameter("market","NG");request.addParameter("quantity","1");request.addParameter("preview","true");var response=new org.springframework.mock.web.MockHttpServletResponse();boolean[] reached={false};
   boundary.doFilter(request,response,(req,res)->{reached[0]=true;var result=controller.price((jakarta.servlet.http.HttpServletRequest)req,f.sku.toString()).getBody();assertThat(result.unitAmount()).isEqualTo("7.00");assertThat(result.minimumQuantity()).isEqualTo("10");});assertThat(reached[0]).isTrue();
   org.springframework.security.core.context.SecurityContextHolder.clearContext();
   var guest=new org.springframework.mock.web.MockHttpServletRequest("GET",route);guest.addParameter("market","NG");guest.addParameter("quantity","1");guest.addParameter("preview","true");boundary.doFilter(guest,new org.springframework.mock.web.MockHttpServletResponse(),(req,res)->assertThat(controller.price((jakarta.servlet.http.HttpServletRequest)req,f.sku.toString()).getBody().unitAmount()).isEqualTo("12.34"));
   var cart=carts.create(f.customer,new CartValues.Create(f.market,null),"browser-context",UUID.randomUUID());var put=new org.springframework.mock.web.MockHttpServletRequest("PUT","/api/v1/carts/"+cart.id()+"/lines/"+f.sku);put.setCookies(new jakarta.servlet.http.Cookie("nigson-local-session",id));put.addHeader("If-Match","\""+cart.version()+"\"");put.addHeader("Idempotency-Key","browser-add-minimum");put.addHeader("X-CSRF-TOKEN",record.csrfToken());var cartController=new CartController(carts);boolean[] added={false};boundary.doFilter(put,new org.springframework.mock.web.MockHttpServletResponse(),(req,res)->{var result=cartController.set((jakarta.servlet.http.HttpServletRequest)req,cart.id().toString(),f.sku.toString(),EventCodec.JSON.readTree("{\"quantity\":\"10\"}")).getBody();assertThat(result.lines().getFirst().quantity()).isEqualTo("10");added[0]=true;});assertThat(added[0]).isTrue();
  }finally{org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 }
 @Test void regularAndAnonymousCustomersKeepRetail(){assertThat(f.prices.price(null,f.sku,"NG","10",null,true).minimumQuantity()).isEqualTo("1");assertThat(f.prices.price(null,f.sku,"NG","2",null).unitAmount()).isEqualTo("12.34");assertThat(f.prices.price(f.customer,f.sku,"NG","2",null).unitAmount()).isEqualTo("12.34");}
 @Test void wholesaleUsesOnlyWholesaleAndPreviewDoesNotRelaxWrites(){partner("WHOLESALE");price("WHOLESALE","7.00","10");price("DISTRIBUTOR","6.00","20");var preview=f.prices.price(f.customer,f.sku,"NG","1",null,true);assertThat(preview.unitAmount()).isEqualTo("7.00");assertThat(preview.minimumQuantity()).isEqualTo("10");assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","1",null)).hasMessage("PRICING_RULE_VIOLATION");var cart=carts.create(f.customer,new CartValues.Create(f.market,null),"canonical-wholesale",UUID.randomUUID());assertThatThrownBy(()->carts.set(f.customer,cart.id(),f.sku,cart.version(),new CartValues.Quantity("1"),"below-minimum",UUID.randomUUID())).hasMessage("CART_RULE_VIOLATION");assertThat(carts.set(f.customer,cart.id(),f.sku,cart.version(),new CartValues.Quantity("10"),"valid-minimum",UUID.randomUUID()).lines().getFirst().quantity()).isEqualTo("10");}
 @Test void distributorUsesDistributorWithoutClientOrganization(){partner("DISTRIBUTOR");price("WHOLESALE","7.00","10");price("DISTRIBUTOR","6.00","20");assertThat(f.prices.price(f.customer,f.sku,"NG","20",null).unitAmount()).isEqualTo("6.00");}
 @Test void missingClearedSuspendedAndAmbiguousClaimsCannotFallBack(){UUID org=partner("WHOLESALE");assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","30",null)).hasMessage("PRICING_RULE_VIOLATION");price("WHOLESALE","7.00","10");f.jdbc.update("UPDATE commerce.standard_sku_price SET price_book_id=NULL WHERE sku_id=?",f.sku);assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","30",null)).hasMessage("PRICING_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.account_entitlement SET status='SUSPENDED',suspended_at=now() WHERE organization_id=?",org);assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","30",null)).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->carts.create(f.customer,new CartValues.Create(f.market,null),"suspended-cart",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.account_entitlement SET status='ACTIVE',suspended_at=NULL WHERE organization_id=?",org);partner("DISTRIBUTOR");assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","30",null)).hasMessage("ACCESS_DENIED");}
 @Test void approvalRefreshPreservesCartAndInvalidatesOldQuotes(){var old=f.quotes.create(f.customer,new PricingValues.QuoteInput(f.cart,f.address,f.carrier,null),"retail-quote",UUID.randomUUID());UUID org=partner("WHOLESALE");price("WHOLESALE","7.00","2");assertThatThrownBy(()->f.quotes.create(f.customer,new PricingValues.QuoteInput(f.cart,f.address,f.carrier,null),"old-context-quote",UUID.randomUUID())).hasMessage("CHECKOUT_REPRICE_REQUIRED");var migrated=carts.create(f.customer,new CartValues.Create(f.market,null),"refresh-approved-cart",UUID.randomUUID());assertThat(migrated.id()).isEqualTo(f.cart);assertThat(migrated.organizationId()).isEqualTo(org);assertThat(migrated.version()).isEqualTo(1);assertThat(migrated.lines().getFirst().quantity()).isEqualTo("2");carts.create(f.customer,new CartValues.Create(f.market,null),"refresh-again",UUID.randomUUID());assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='CART_SET'",Integer.class,f.cart)).isEqualTo(1);assertThatThrownBy(()->new TransactionTemplate(f.manager).execute(s->f.checkoutPricing.require(f.customer,old.id(),old.quoteHash()))).hasMessage("CHECKOUT_REPRICE_REQUIRED");f.jdbc.update("UPDATE commerce.carrier_quote SET cart_version=? WHERE id=?",migrated.version(),f.carrier);var quote=f.quotes.create(f.customer,new PricingValues.QuoteInput(f.cart,f.address,f.carrier,null),"business-quote",UUID.randomUUID());assertThat(quote.lines().getFirst().unitAmount()).isEqualTo("7.00");price("WHOLESALE","8.00","2");assertThatThrownBy(()->new TransactionTemplate(f.manager).execute(s->f.checkoutPricing.require(f.customer,quote.id(),quote.quoteHash()))).hasMessage("CHECKOUT_REPRICE_REQUIRED");}
 @Test void explicitCustomAssignmentWinsAndForeignOrganizationIsDenied(){UUID org=partner("DISTRIBUTOR");price("DISTRIBUTOR","6.00","2");var base=f.input("5.00");var draft=f.books.create(f.sales,new PricingValues.Input(f.code+"_CUSTOM","NGN","DISTRIBUTOR",base.effectiveFrom(),base.effectiveUntil(),List.of(new PricingValues.Entry(f.sku,"2","5.00"))),"custom-create",UUID.randomUUID());var custom=f.books.activate(f.finance,draft.id(),0,"Synthetic custom activation","custom-active",UUID.randomUUID());f.assignments.assign(f.sales,org,0,new PricingValues.AssignmentInput(f.market,custom.id(),List.of()),"custom-assignment",UUID.randomUUID());assertThat(f.prices.price(f.customer,f.sku,"NG","2",null).unitAmount()).isEqualTo("5.00");assertThatThrownBy(()->f.prices.price(f.customer,f.sku,"NG","2",UUID.randomUUID())).hasMessage("ACCESS_DENIED");}
}

